urlset:
{% for url in static_urls %}

  {{ url.loc }}
  daily
  {{ url.priority }}

{% endfor %}

{% for movie in movies %}

  {{ host }}{{ url_for('main.movie_details', det='movie', name=movie.slug, id=movie.id, _external=False) }}
  {{ (movie.updated_at or movie.date_added).strftime('%Y-%m-%d') if (movie.updated_at or movie.date_added) else '2025-01-01' }}
  weekly
  0.8

{% endfor %}

{% for item in series_list %}

  {{ host }}{{ url_for('main.series_details', det='series', name=item.slug, id=item.id, season=1, episode=1, _external=False) }}
  {{ (item.updated_at or item.date_added).strftime('%Y-%m-%d') if (item.updated_at or item.date_added) else '2025-01-01' }}
  weekly
  0.8

{% endfor %}

{% for episode in episodes %}
{% set series_video = episode.season.series.all_video %}

  {{ host }}{{ url_for('main.series_details', det='series', name=series_video.slug, id=series_video.id, season=episode.season.season_number, episode=episode.episode_number, _external=False) }}
  {{ (episode.updated_at or episode.date_added).strftime('%Y-%m-%d') if (episode.updated_at or episode.date_added) else '2025-01-01' }}
  weekly
  0.7

{% endfor %}

{% for trailer in trailers %}

  {{ host }}{{ url_for('main.watch_trailer', det='trailer_watch', name=trailer.slug, _external=False) }}
  monthly
  0.6

{% endfor %}
